import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.StringTokenizer

// (づ°ω°)づﾐe★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
class Solution {
    fun solve() {
        val n = readInt()
        val m = readInt()

        if (m == 1)
            write(n - 1)
        else
            write(1L * n * (m - 1))
    }

    companion object {
        @JvmStatic
        private lateinit var reader: BufferedReader
        @JvmStatic
        private lateinit var writer: PrintWriter
        @JvmStatic
        private var tokenizer: StringTokenizer? = null

        @JvmStatic
        fun main(args: Array<String>) {
            reader = BufferedReader(InputStreamReader(System.`in`))
            writer = PrintWriter(System.out)

            try {
                Solution().solve()
            } catch (ex: Exception) {
                throw ex
            }

            reader.close()
            writer.close()
        }

        private fun nextToken(): String {
            while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
                tokenizer = StringTokenizer(reader.readLine())
            }
            return tokenizer!!.nextToken()
        }

        fun readInt(): Int = nextToken().toInt()
        fun readLong(): Long = nextToken().toLong()
        fun readDouble(): Double = nextToken().toDouble()

        fun readIntArray(): IntArray {
            val st = StringTokenizer(reader.readLine())
            val list = mutableListOf<Int>()
            while (st.hasMoreTokens()) list.add(st.nextToken().toInt())
            return list.toIntArray()
        }

        fun readLongArray(): LongArray {
            val st = StringTokenizer(reader.readLine())
            val list = mutableListOf<Long>()
            while (st.hasMoreTokens()) list.add(st.nextToken().toLong())
            return list.toLongArray()
        }

        fun readDoubleArray(): DoubleArray {
            val st = StringTokenizer(reader.readLine())
            val list = mutableListOf<Double>()
            while (st.hasMoreTokens()) list.add(st.nextToken().toDouble())
            return list.toDoubleArray()
        }

        fun readIntMatrix(numberOfRows: Int): Array<IntArray> {
            return Array(numberOfRows) { readIntArray() }
        }

        fun readAndTransposeIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = readIntMatrix(numberOfRows)
            val ret = Array(matrix[0].size) { IntArray(numberOfRows) }
            for (i in ret.indices) {
                for (j in 0 until numberOfRows) {
                    ret[i][j] = matrix[j][i]
                }
            }
            return ret
        }

        fun readLines(quantity: Int): Array<String> {
            return Array(quantity) { reader.readLine().trim() }
        }

        fun writeArray(array: Iterable<Any?>) {
            writer.println(array.joinToString(" "))
            writer.flush()
        }

        fun write(vararg array: Any?) {
            writeArray(array.asList())
        }

        fun <T> writeLines(array: Iterable<T>) {
            for (a in array) writer.println(a)
            writer.flush()
        }

        private class SDictionary<TKey, TValue> : HashMap<TKey, TValue>() {
            operator fun get(key: TKey): TValue? {
                return if (containsKey(key)) super.get(key) else null
            }

            operator fun set(key: TKey, value: TValue) {
                super.put(key, value)
            }
        }

        fun <T : Any> init(size: Int, supplier: () -> T): Array<T> {
            return Array(size) { supplier() }
        }
    }
}

